pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});
pm.test("Yanıt JSON formatında olmalı", function () {
    pm.response.to.be.json;
    });

pm.test("Arama isteği 200 OK dönmeli", function () {
    pm.response.to.have.status(200);
});

pm.test("Arama yanıtı geçerli JSON olmalı", function () {
    pm.response.to.be.json;
});

pm.test("Arama sonucu ürün listesi içermeli", function () {
    const response = pm.response.json();

    pm.expect(response.data).to.be.an("array");
});

pm.test("Bulunan ürünler pliers aramasıyla eşleşmeli", function () {
    const response = pm.response.json();

    response.data.forEach(function (product) {
        const searchableText =
            (product.name + " " + product.description).toLowerCase();

        pm.expect(searchableText).to.include("pliers");
    });
});

pm.test("Ürün detay isteği 200 OK dönmeli", function () {
    pm.response.to.have.status(200);
});

pm.test("Ürün detay yanıtı geçerli JSON olmalı", function () {
    pm.response.to.be.json;
});

pm.test("Yanıttaki ürün kimliği istenen ürünle eşleşmeli", function () {
    const product = pm.response.json();

    pm.expect(product.id).to.eql("01M6VJPBMABB2CJXWPBT0MHTEJ");
});

pm.test("Ürün adı boş olmamalı", function () {
    const product = pm.response.json();

    pm.expect(product.name).to.be.a("string").and.not.empty;
});

pm.test("Geçersiz ürün için 404 dönmeli", function () {
    pm.response.to.have.status(404);
});

pm.test("Yanıt JSON formatında olmalı", function () {
    pm.response.to.be.json;
});

pm.test("Yanıt bir hata mesajı içermeli", function () {
    const data = pm.response.json();

    pm.expect(
        data.message || data.error
    ).to.be.a("string").and.not.empty;
});

